/* Betriebswirtschaft zuerst: Die Konten bilden den zuvor beschriebenen Vorgang ab. */
(function(root){
'use strict';
const B=root.BioCasa,L=root.BioCasaLearning;
const CASES=[
 {ls:'LS02 · G1',title:'Zutaten treffen ein – bezahlt wird später',story:'Aluna nimmt Bio-Mehl, Tomatenpüree und weitere Zutaten für die Pizzaproduktion im Wert von 8.000 € entgegen. Lieferung und Rechnung liegen vor. BioCasa hat die Zutaten bereits erhalten, die Rechnung aber noch nicht bezahlt. Im Grundlagenfenster wird neue Umsatzsteuer ausdrücklich ausgeblendet.',parts:{200:'Die gelieferten Zutaten gehören jetzt BioCasa.',440:'BioCasa muss dem Lieferanten die Rechnung noch bezahlen.'},question:'Was entsteht durch diesen Einkauf auf Ziel?',choices:[['expense','Sofort 8.000 € Materialaufwand'],['stock-debt','8.000 € mehr Vorräte und 8.000 € mehr Lieferantenschulden'],['bank','8.000 € mehr Bankguthaben']],answer:'stock-debt',hint:'Unterscheide erhaltenes, noch nicht verbrauchtes Material von einer späteren Zahlung.'},
 {ls:'LS02 · G2',title:'Büromöbel ersetzen verfügbares Bankgeld',story:'BioCasa erhält zusätzliche, langfristig nutzbare Büromöbel für 1.200 € und bezahlt sofort per Bank. Lieferbeleg und Kontoauszug dokumentieren denselben Geschäftsvorfall.',parts:{'087':'Die neuen Möbel stehen dem Unternehmen dauerhaft zur Verfügung.','280':'Die Bank hat die Überweisung ausgeführt.'},question:'Was erklärt diesen Vorgang?',choices:[['swap','Vermögen wird umgeschichtet: mehr Ausstattung, weniger Bankguthaben'],['loss','Die gesamte Zahlung ist sofort ein Verlust'],['double','Lieferbeleg und Bankbeleg sind zwei verschiedene Einkäufe']],answer:'swap',hint:'Zwei Belege können zu einem Geschäftsvorfall gehören. Prüfe die dauerhafte Nutzung der Möbel.'},
 {ls:'LS02 · G3',title:'Geld wechselt seinen Aufbewahrungsort',story:'Aluna hebt 2.000 € vom betrieblichen Bankkonto ab und legt den gesamten Betrag in die Geschäftskasse. BioCasa hat danach mehr Bargeld und entsprechend weniger Bankguthaben.',parts:{'288':'Das abgehobene Geld liegt jetzt in der Geschäftskasse.','280':'Derselbe Betrag steht nicht mehr auf dem Bankkonto.'},question:'Was passiert mit den gesamten flüssigen Mitteln?',choices:[['up','Sie steigen um 2.000 €'],['same','Sie bleiben insgesamt gleich'],['down','Sie sinken um 2.000 €']],answer:'same',hint:'Betrachte Kasse und Bank gemeinsam.'},
 {ls:'LS02 · G4',title:'Eine vorhandene Lieferantenschuld wird teilweise bezahlt',story:'Von der bereits gebuchten Rohstoffrechnung aus G1 bezahlt BioCasa 3.000 € per Bank. Es wird jetzt keine neue Ware geliefert. Ein Teil der bisherigen Verpflichtung erlischt.',parts:{'440':'Der Lieferant kann 3.000 € weniger von BioCasa verlangen.','280':'BioCasa überweist 3.000 € vom Bankkonto.'},question:'Warum wird Konto 200 Rohstoffe hier nicht erneut erhöht?',choices:[['new','Weil die Zahlung einen weiteren Einkauf auslöst'],['already','Weil der Materialzugang bereits bei der Lieferung in G1 gebucht wurde'],['expense','Weil jede Überweisung stattdessen Aufwand ist']],answer:'already',hint:'Trenne den Zeitpunkt des Materialzugangs vom Zeitpunkt seiner Bezahlung.'},
 {ls:'LS02 · G5',title:'Der Gläubiger wechselt – ohne Geld auf BioCasas Konto',story:'Eine Bank löst weitere 2.000 € der Lieferantenschuld durch ein neu vereinbartes langfristiges Darlehen ab. Sie bezahlt unmittelbar an den Lieferanten. BioCasa schuldet den Betrag danach der Bank statt dem Lieferanten.',parts:{'440':'Die bisherige Lieferantenschuld wird um 2.000 € geringer.','425':'An ihre Stelle tritt eine neue langfristige Darlehensschuld.'},question:'Welche Aussage passt zur direkten Zahlung der Bank?',choices:[['bank-up','BioCasas Bankguthaben steigt um 2.000 €'],['profit','Der Gläubigerwechsel erzeugt einen Gewinn'],['no-bank','BioCasas laufendes Bankkonto wird nicht berührt']],answer:'no-bank',hint:'Verfolge, wer an wen zahlt. Die Bank zahlt hier nicht auf BioCasas Konto ein.'},
 {ls:'LS02 · G6',title:'Die Entwicklungsküche wächst – finanziert durch einen Kredit',story:'BioCasa erhält zusätzliche eigene Ausstattung für die Entwicklungsküche im Wert von 4.500 €. Ein zusätzliches langfristiges Darlehen finanziert sie vollständig. Die Bank bezahlt unmittelbar den Verkäufer.',parts:{'085':'BioCasa kann die zusätzliche Küchenausstattung dauerhaft nutzen.','425':'BioCasa muss das dafür aufgenommene Darlehen später zurückzahlen.'},question:'Was wächst durch diesen Vorgang?',choices:[['both','Vermögen und langfristige Schulden'],['cash','Nur die Kasse'],['profit','Der Gewinn um 4.500 €']],answer:'both',hint:'Die neue Ausstattung und ihre Finanzierung sind zwei Seiten desselben Vorgangs.'},
 {ls:'LS02 · G7',title:'Ein Teil der Darlehensschuld wird zurückgezahlt',story:'Im ausdrücklich getrennten LS02-Übungsfenster leistet BioCasa eine zulässige freiwillige Sondertilgung von 5.000 € per Bank. Die Zahlung enthält keine Zinsen. Sie ist nicht die reguläre Pflichttilgung des tilgungsfreien Gründungsdarlehens.',parts:{'425':'Der zurückzuzahlende Darlehensbetrag sinkt.','280':'Das Bankguthaben sinkt um den überwiesenen Betrag.'},question:'Welche Wirkung hat die reine Tilgung auf das Ergebnis?',choices:[['loss','Sie senkt den Gewinn um 5.000 €'],['gain','Sie erhöht den Gewinn um 5.000 €'],['neutral','Sie verändert das Ergebnis nicht']],answer:'neutral',hint:'Tilgung vermindert eine vorhandene Schuld. Zinsen wären ein anderer Vorgang.'},
 {ls:'LS02 · G8',title:'Verpackungen werden bevorratet',story:'BioCasa kauft Pizzakartons und Folie für 1.000 € und bezahlt sofort per Bank. Die Verpackungen werden zunächst eingelagert und noch nicht verbraucht. Die Reihe behandelt sie in diesem Fall als Hilfsstoffe.',parts:{'202':'Die noch unbenutzten Verpackungen erhöhen den Hilfsstoffvorrat.','280':'Die Bezahlung vermindert das Bankguthaben.'},question:'Wann entsteht im Modell der Materialaufwand?',choices:[['receipt','Immer schon beim Eingang der Verpackungen'],['consume','Bei der Entnahme beziehungsweise beim Verbrauch'],['never','Verpackungen können nie Aufwand verursachen']],answer:'consume',hint:'Noch vorhandene und erst später verbrauchte Verpackungen sind zunächst Vorräte.'},
 {ls:'LS03 / LS06 · OS-01',title:'Material wird für eine verkaufte Pizza-Charge verbraucht',story:'Für die verkaufte Charge werden Rohstoffe aus dem Vorrat entnommen. Im zusätzlichen OS-Beleg sind das 1.000 kg Rohstoffmix mit einem Wert von 4.000 €. Der Vorrat steht BioCasa danach nicht mehr zur Verfügung.',parts:{'600':'Der Verbrauch verursacht Materialaufwand.','200':'Der noch vorhandene Rohstoffvorrat sinkt.'},question:'Was ist die Ergebniswirkung des Verbrauchs?',choices:[['same','Keine, weil nur eine Lagerbewegung vorliegt'],['down','Der Aufwand vermindert das Ergebnis'],['up','Die Entnahme ist ein Verkaufserlös']],answer:'down',hint:'Eine Materialentnahme ist im Unterschied zum bloßen Einkauf erfolgswirksam.'},
 {ls:'LS03 / LS04 · OS-02',title:'Eigene Bio-Pizzen werden verkauft und bezahlt',story:'BioCasa hat die vereinbarte Lieferung eigener Bio-Pizzen erbracht. Der Nettopreis der zusätzlichen OS-Charge beträgt 25.000 €, die vorgegebene Umsatzsteuer 1.750 €. Die Kundschaft bezahlt 26.750 € auf das Bankkonto.',parts:{'280':'Der vollständige Bruttobetrag geht auf dem Bankkonto ein.','5000':'Die erfüllte Lieferung begründet den Nettoerlös.','480':'Der Steueranteil ist gegenüber dem Finanzamt abzurechnen.'},question:'Welcher Betrag gehört zum Umsatzerlös?',choices:[['gross','26.750 € einschließlich Steuer'],['net','25.000 € ohne Umsatzsteuer'],['tax','Nur der Steueranteil von 1.750 €']],answer:'net',hint:'Umsatzsteuer ist ein durchlaufender Abrechnungsbetrag, kein eigener Umsatzerlös.'},
 {ls:'LS03 · OS-03',title:'Die gemietete Halle wird betrieblich genutzt',story:'BioCasa nutzt die Halle in Aurich-Schirum für die Produktion. Für die im OS-Beleg erfasste Nutzungszeit zahlt das Unternehmen 8.900 € Miete vom Bankkonto. Die Zahlung betrifft laufende Nutzung.',parts:{'670':'Die laufende Nutzung der gemieteten Räume verursacht Aufwand.','280':'Die Mietzahlung verringert das verfügbare Bankguthaben.'},question:'Welche Wirkung gehört zur laufenden Miete?',choices:[['asset','Die gemietete Halle wird Eigentum von BioCasa'],['expense','Mietaufwand und Bankabgang entstehen gleichzeitig'],['debt','Jede Miete tilgt das Gründungsdarlehen']],answer:'expense',hint:'Nutzung gemieteter Räume und Kauf einer eigenen Halle sind verschiedene Vorgänge.'},
 {ls:'LS03 · OS-04',title:'Beschäftigte werden für ihre Arbeit bezahlt',story:'BioCasa bezahlt im vereinfachten OS-Fall 5.000 € Gehälter für bereits erbrachte Arbeit. Die Auszahlung erfolgt über die Bank. Eine vollständige Lohnabrechnung ist in diesem Beleg nicht dargestellt.',parts:{'630':'Die erbrachte Arbeit verursacht Personalaufwand.','280':'Die Auszahlung senkt das Bankguthaben.'},question:'Welches Konto bildet den Personalaufwand dieses Belegs ab?',choices:[['630','630 Gehälter'],['300','300 Gezeichnetes Kapital'],['425','425 Langfristige Bankverbindlichkeiten']],answer:'630',hint:'Lies die Bezeichnung des Personalaufwandskontos.'},
 {ls:'LS03 / LS04 · OS-05',title:'Strom wird verbraucht und die Rechnung beglichen',story:'BioCasa bezahlt eine Energierechnung über 714 € brutto. Davon betreffen 600 € den verbrauchten Strom und 114 € die im Übungsfall abzugsfähige Vorsteuer.',parts:{'605':'Der verbrauchte Strom erzeugt 600 € Energieaufwand.','260':'Die Vorsteuer ist ein eigener Anspruch gegen das Finanzamt.','280':'Der Bruttobetrag von 714 € wird überwiesen.'},question:'Wie hoch ist der Energieaufwand?',choices:[['114','114 €'],['714','714 €'],['600','600 €']],answer:'600',hint:'Trenne den Wert der Leistung vom abzugsfähigen Steueranteil.'},
 {ls:'LS05 · OS-06',title:'Die Siegeleinheit verliert durch Nutzung an Buchwert',story:'Die eigene Siegeleinheit wird genutzt und altert. Im zusätzlichen OS-Beleg werden 1.000 € Abschreibung erfasst. Für diese Wertminderung wird jetzt kein Geld überwiesen.',parts:{'652':'Die periodische Wertminderung wird zum Aufwand.','076':'Der ausgewiesene Buchwert der Siegeleinheit sinkt.'},question:'Was unterscheidet diese Abschreibung von einer Auszahlung?',choices:[['no-cash','Die Abschreibung mindert das Ergebnis ohne aktuellen Geldabgang'],['bank','Jede Abschreibung senkt das Bankguthaben'],['revenue','Die Wertminderung erzeugt einen Erlös']],answer:'no-cash',hint:'Prüfe, ob in dieser Buchung überhaupt ein Geldkonto vorkommt.'},
 {ls:'LS03 · OS-07',title:'Die Nutzung von Fremdkapital kostet Zinsen',story:'Für die Bereitstellung des Darlehens zahlt BioCasa im zusätzlichen OS-Beleg 200 € Zinsen per Bank. Es handelt sich um Finanzierungskosten, nicht um die Rückzahlung des Darlehensbetrags.',parts:{'751':'Die Kreditnutzung verursacht Zinsaufwand.','280':'Die Zinszahlung verringert das Bankguthaben.'},question:'Was passiert mit der Darlehensschuld auf Konto 425?',choices:[['down','Sie sinkt automatisch um 200 €'],['same','Sie bleibt durch diese reine Zinszahlung unverändert'],['up','Sie steigt automatisch um 200 €']],answer:'same',hint:'Unterscheide den Preis für die Kapitalnutzung von einer Tilgung.'}
];
function adjustedInfo(entry){
 const c=B.clone(CASES[entry.id-1]),data=root.BioCasaData;if(!data)return c;const original=data.defaultConfig.demoEntries[entry.id-1],format=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(n),replacements={};
 for(const [id,debit,credit] of original.lines){const line=entry.lines.find(l=>l.account===id);if(line)replacements[format(debit||credit)]=format((line.debit||line.credit)/100);}
 if(original.movement&&entry.movement)replacements[format(Math.abs(original.movement.qty))+' kg']=format(Math.abs(entry.movement.qty))+' kg';
 const keys=Object.keys(replacements).sort((a,b)=>b.length-a.length),escape=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),pattern=new RegExp('(^|[^0-9.,])('+keys.map(escape).join('|')+')(?![0-9.,])','g');
 const walk=x=>typeof x==='string'?x.replace(pattern,(all,before,value)=>before+replacements[value]):Array.isArray(x)?x.map(walk):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).map(([k,v])=>[k,walk(v)])):x;
 return {...c,story:walk(c.story),parts:walk(c.parts),question:walk(c.question),hint:walk(c.hint),choices:c.choices.map(([key,label])=>[key,walk(label)])};
}
function info(entry){if(entry.source==='seed'&&CASES[entry.id-1])return adjustedInfo(entry);return {ls:entry.task==='bank'?'LS02 · eigener Transferauftrag':'Eigener Geschäftsvorfall',title:entry.text,story:entry.task==='bank'?'Christian hat 200 € aus der Geschäftskasse auf das Bankkonto eingezahlt. Bargeld wird zu Bankguthaben; es gibt weder eine neue Leistung noch einen Aufwand.':`Dein Beleg beschreibt: ${entry.text}. Die folgenden Konten bilden die von dir erfassten Wertänderungen ab. Prüfe ihre Übereinstimmung mit dem tatsächlichen Vorgang.`,parts:{}};}
function recordCase(state,id,answer){
 if(root.BioCasaLearning.accessStage(state)<4)throw Error('Zuerst die Grundlagen bis zu den Bestandskonten bearbeiten.');
 const entry=B.journal(state).find(e=>e.id===id&&e.source==='seed'),c=entry&&CASES[id-1];if(!c)throw Error('Für diesen Beleg gibt es keinen gespeicherten Lerncheck.');
 if(answer!==c.answer)return {state:null,hint:c.hint};
 const next=B.clone(state);next.learning=B.clone(L.data(state));if(!next.learning.cases.includes(id))next.learning.cases.push(id);next.revision++;return {state:next};
}
root.BioCasaTutorials=Object.freeze({CASES,info,recordCase});
})(globalThis);
